INSERT INTO `dgw_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2021-06-10 17:33:01', '2021-06-10 09:33:01', '<!-- wp:paragraph -->\n<p>歡迎使用 WordPress。這是這個網站的第一篇文章，試試為這篇文章進行編輯或直接刪除，然後開始撰寫新文章！</p>\n<!-- /wp:paragraph -->', '網站第一篇文章', '', 'publish', 'open', 'closed', '', 'hello-world', '', '', '2021-06-10 17:33:01', '2021-06-10 09:33:01', '', 0, 'http://digiwin.astcc24.net/?p=1', 0, 'post', '', 1),
(55, 1, '2021-06-15 10:58:30', '2021-06-15 02:58:30', 'Các doanh nghiệp đều dốc sức theo đuổi tốc độ phát triển và sự sáng tạo, do vậy các sản phẩm cần đa dạng hóa,cần nhanh chóng đáp ứng linh hoạt sự thay đổi của thị trường, từ đó đạt được sự hài lòng của khách hàng.<!--more-->\r\n\r\nNgoài ra, sản phẩm còn phải phối hợp với chiến lược của đối tác, thậm chí tối ưu và toàn cầu hóa công việc điều hành trở thành yếu tố không thể thiếu để doanh nghiệp nhanh chóng phát triển. Một doanh nghiệp thành công không thể chỉ hài lòng với hiện tại vì đối thủ cạnh tranh luôn theo sát phía sau, do đó doanh nghiệp không thể chỉ hài lòng với việc áp dụng hệ thống ERP,ngoài việc doanh nghiệp phải có mô hình hoạt động đúng đắn ra, cần hiểu rõ việc tăng cường chức năng quản lý của công nghệ thông tin để tối ưu hóa các khía cạnh vận hành của doanh nghiệp, giúp hiệu suất của các phòng ban có thể kết hợp chặt chẽ với mô hình hoạt động của doanh nghiệp.\r\n\r\nTIPTOP GP được thiết kế dựa theo cốt lõi của ERP, vận dụng thông tin chuyên sâu vào quản lý doanh nghiệp, giá trị chuỗi hoạt động kinh doanh và quản lý thông tin. Dựa vào góc độ quản lý doanh nghiệp, từ phương diện điều hành, quản lý, ra quyết định để quy trình nội bộ doanh nghiệp liên kết với nhau, phát huy hết mức hiệu quả quản lý. Từ góc độ giá trị chuỗi hoạt động kinh doanh, giúp nội bộ doanh nghiệp hợp tác với bên ngoài, nâng cao chất lượng sản phẩm và hiệu lực của hoạt động thương mại, từ góc độ quản lý thông tin, cung cấp các công cụ để nhanh chóng phát triển các ứng dụng nhằm đáp ứng với sự thay đổi mô hình kinh doanh của doanh nghiệp.', '第一則-越文', '', 'publish', 'closed', 'closed', '', 'slider-one', '', '', '2021-10-19 11:33:01', '2021-10-19 03:33:01', '', 0, 'http://digiwin.astcc24.net/?post_type=slider&#038;p=55', 0, 'slider', '', 0),
(57, 1, '2021-06-15 11:01:56', '2021-06-15 03:01:56', '', '105531', '', 'inherit', 'open', 'closed', '', '105531', '', '', '2021-06-15 11:01:56', '2021-06-15 03:01:56', '', 55, 'http://digiwin.astcc24.net/wp-content/uploads/2021/06/105531.jpg', 0, 'attachment', 'image/jpeg', 0),
(58, 1, '2021-06-15 11:12:59', '2021-06-15 03:12:59', '<p class=\"pc\">鼎捷软件ERP产品，全面提升企业运营效益</p>\r\n产品线涵盖不同企业的发展规模，以客户效益为核心为企业提供全程价值服务\r\n\r\n南非主要發生在豪登省及誇祖魯納塔爾省的騷亂未平息，有購物中心更發生人踩人慘劇。連日騷亂增至最少72人死亡，過千人被捕。官員警告若搶掠持續，部分地區的基本食物供應，可能用盡，但認為目前毋須宣布國家進入緊急狀態。<!--more-->\r\n\r\n國家安全部長說，國安局及國家警察局之間，正在共享資訊，目前已產生效果，避免兩省遭受因騷亂導致的更大破壞。警方就說已召回所有休假警員，加強各地警力，並監控所有社交網絡，追蹤煽動暴力的帖文及資訊來源。國防軍目前派出2500名軍人，協助警方制止搶掠，平定騷亂。\r\n\r\n豪登省省長馬庫拉說，疫情令失業及糧食不足問題惡化，有人趁政治局勢不穩定，乘機犯事，呼籲民眾停止搶掠行為，以免經濟和社會受進一步打擊。', '第二則', '', 'publish', 'closed', 'closed', '', 'silder-2', '', '', '2022-02-11 11:59:59', '2022-02-11 03:59:59', '', 0, 'http://digiwin.astcc24.net/?post_type=slider&#038;p=58', 0, 'slider', '', 0),
(106, 1, '2021-06-22 17:16:26', '2021-06-22 09:16:26', '', 'ten san pham viet', '', 'publish', 'closed', 'closed', '', '%e8%87%aa%e5%8b%95%e8%8d%89%e7%a8%bf', '', '', '2021-06-22 18:12:46', '2021-06-22 10:12:46', '', 0, 'http://digiwin.astcc24.net/?post_type=solution&#038;p=106', 0, 'solution', '', 0),
