(526, 1, '2021-10-19 10:44:15', '2021-10-19 02:44:15', '', '數位啟動_首頁幻燈片1300X430-1', '', 'inherit', 'open', 'closed', '', '%e6%95%b8%e4%bd%8d%e5%95%9f%e5%8b%95_%e9%a6%96%e9%a0%81%e5%b9%bb%e7%87%88%e7%89%871300x430-1', '', '', '2021-10-19 10:44:15', '2021-10-19 02:44:15', '', 243, 'http://localhost/digiwin/wp-content/uploads/2021/07/數位啟動_首頁幻燈片1300X430-1.jpg', 0, 'attachment', 'image/jpeg', 0),
