INSERT INTO `dgw_vote` (`ID`, `title`, `content`, `note`, `status`, `create_date`, `update_date`, `trash`) VALUES
(4, 'titel 5', '<p>content 3 aaa</p>', 'note 3', '0', '02-20-2002', '06-02-2023', '0'),
(5, 'title 4', '<p>noi dung aaaaaaafsdf</p>', '', '1', '06-02-2023', '06-02-2023', ''),
(6, 'Bloomberg cho hay, quy định hạn chế trên áp dụng', '<p>Bloomberg cho hay, quy định hạn chế trên áp dụng với các bộ phận khác nhau của gã khổng lồ phố Wall. Nguyên nhân không bắt nguồn từ sự cố cụ thể nào mà là một phần trong “các biện pháp kiểm soát đối với phần mềm của bên thứ ba”<!--more--></p>\r\n<p>Trước đó, vào đầu tháng 1, CEO Jamie Dimon nói rằng, JP Morgan Chase đã chi “hàng trăm triệu USD mỗi năm” để tích hợp AI vào hoạt động của công ty.</p>\r\n<p>Đối với ChatGPT, ngân hàng này lo ngại dữ liệu phản hồi sẽ được sử dụng bởi các nhà phát triển để tăng hiệu quả thuật toán hoặc các dữ liệu nhạy cảm bị truy cập bởi các kỹ sư.</p>', '', '0', '06-02-2023', '24-02-2023', '');
